export const read = f => { try { return f(); } catch { return null; } };
export function all(fs) { for (const f of fs) { try { f(); } catch (e) { continue; } } }
export let v = 0;
export const set = f => { try { v = f(); } catch { v = -1; } };

export const r1 = f => { try { return f(); } catch (e) { if (e.code !== 'ENOENT') throw e; return null; } };
export const r2 = f => { try { return f(); } catch { return null; } }; // gone: the file was removed meanwhile, the caller makes a new one
export const r3 = f => { try { return f(); } catch (err) { return { error: err.message }; } };
